nodes.statement:
The set $\Omega_2$ is equivalent to
	\begin{equation*}
		\Omega_2^* := \left\{
		\mathbf{U} \in \mathbb{R}^3 
		: 
		\rho > 0, \; z > 0, \; \mathbf{U} \cdot \mathbf{n}_* + s_* \geq 0 \quad \forall \; \rho_* > 0, \; z_* > 0 
		\right\},
	\end{equation*}
	where $\mathbf{n}_* := \mathbf{n}(\rho_*,z_*)$, $s_* := s(\rho_*,z_*)$, 
	\begin{equation*}
		\begin{aligned}
			\mathbf{n}(\rho,z) &:= - \left(v_{\min} + p (\rho, z) + \rho p_\rho(\rho, z), -1, \rho p_{z} (\rho, z) \right)^\top,
			\\
			s(\rho,z) &:= \rho^2 p_\rho (\rho, z) + \rho z p_z (\rho, z).
		\end{aligned}
	\end{equation*}

If  $\widehat{\mathbf{U}} = (\hat{\rho},\hat{y},\hat{z})^\top \in \Omega_2^*$ 
	and $\widecheck{\mathbf{U}} = (\check{\rho},\check{y},\check{z})^\top \in \Omega_2^*$, then 
	$\mathrlap{ \raisebox{0.6 pt}{$\widecheck{\phantom{\mathbf{U}}}$} } \mathrlap{ \raisebox{-0.6 pt}{$\widehat{\phantom{\mathbf{U}}}$} } \mathbf{U} = (\mathrlap{ \raisebox{0.5 pt}{$\check{\phantom{\rho}}$} } \mathrlap{ \raisebox{-0.5 pt}{$\hat{\phantom{\rho}}$} } \rho,\mathrlap{ \raisebox{0.5 pt}{$\check{\phantom{y}}$} } \mathrlap{ \raisebox{-0.5 pt}{$\hat{\phantom{y}}$} } y,\mathrlap{ \raisebox{0.5 pt}{$\check{\phantom{z}}$} } \mathrlap{ \raisebox{-0.5 pt}{$\hat{\phantom{z}}$} } z)^\top$ $:= \mathcal{S}_{\tt GLF}(\widehat{\mathbf{U}},\widecheck{\mathbf{U}})	\in \Omega^*_2	$,
	or equivalently, the inequality
	\begin{equation}
		\mathrlap{ \raisebox{0.6 pt}{$\widecheck{\phantom{\mathbf{U}}}$} } \mathrlap{ \raisebox{-0.6 pt}{$\widehat{\phantom{\mathbf{U}}}$} } \mathbf{U} \cdot \mathbf{n}_* + s_* \geq 0
	\end{equation}
	holds for any $\rho_* > 0, z_* > 0$, under the condition
	\begin{equation}
		\alpha \geq 
		\alpha_{\max}(\widehat{\mathbf{U}},\widecheck{\mathbf{U}})
		:=
		\max
		\Big\{ 
		\alpha_{\rm std}
		,
		|v(\widehat{\mathbf{U}})|+\overline{s}(\widehat{\mathbf{U}},\widecheck{\mathbf{U}})/\,\hat{\rho}
		,
		|v(\widecheck{\mathbf{U}})|+\overline{s}(\widehat{\mathbf{U}},\widecheck{\mathbf{U}})/\,\check{\rho}\,
		\Big\}.
	\end{equation}
	Here, 
	$\alpha_{\rm std} := \max \{ \overline\alpha(\widehat{\mathbf{U}}), \overline\alpha(\widecheck{\mathbf{U}})\}$, $\overline \alpha(\mathbf{U})$ $:= v + |\rho p_{\rho}+z p_z|$ is an estimate of the maximum propagation speed,
	\begin{equation}
		\overline{s}(\widehat{\mathbf{U}},\widecheck{\mathbf{U}})
		:=
		\max_
		{\substack{
				\rho \in [\underline{\rho},\overline{\rho}]
				\\
				z \in [\underline{z},\overline{z}]
			}
		}
		s(\rho,z)
		=
		\begin{dcases}
			v_{\rm ref}
			\overline{z}^{\,\kappa}\,
			\underline{\rho}^{\gamma-\kappa}
			&
			{\rm if}~ \gamma > 0,
			\\
			v_{\rm ref} \, \overline\rho 
			&
			{\rm if}~ \gamma = 0,
		\end{dcases}
	\end{equation}
	\begin{align*}
		\underline{\rho} &:=\min \left\{{\rho}_1,{\rho}_2\right\},&
		\;
		\overline{\rho}  &:= \max	\left\{{\rho}_1,{\rho}_2\right\},&
		\;
		{\rho}_1 &:= \frac{\hat{\rho}+\check{\rho}}{2},&
		\;
		{\rho}_2 &:= {\rho}_1 + \frac{\hat{\rho}\;\hat{v} - \check{\rho}\;\check{v}}{2 \alpha_{\rm std}},
		\\
		\underline{z} &:= \min \left\{z_1,{z}_2\right\},&
		\;
		\overline{z} &:= \max \left\{{z}_1,{z}_2\right\},&
		\;
		{z}_1 &:= \frac{\hat{z}+\check{z} }{2},&
		\;
		{z}_2 &:= z_1 + \frac{\hat{z}\;\hat{v} - \check{z}\;\check{v}}{2 \alpha_{\rm std}}.
	\end{align*}

Considering an invariant domain $\Omega$ in the form of (2.2), if 
	$\mathbf{U}^{-}_{j-\frac12} \in \Omega$, $\mathbf{U}^{+}_{j+\frac12} \in \Omega$, $\mathbf{U}(x^{\tt GL}_{j,\ell}) \in \Omega$ for any $\ell = 1,\dots,L$,
	then the result of the FE step (4.13) with 
	\[
	\alpha \ge \max \big\{ \alpha_{\max}(\mathbf{U}^{-}_{j-\frac12},\mathbf{U}^{+}_{j-\frac12}), \alpha_{\max}(\mathbf{U}^{-}_{j+\frac12},\mathbf{U}^{+}_{j+\frac12}) \big\}
	\]
	satisfies $\overline{\mathbf{U}}^*_j \in \Omega$, under the CFL condition 
	\begin{equation}
		\alpha \frac{\Delta t}{\Delta x} \le \omega^{\tt GL}_1.
	\end{equation}

If the global invariant domains $\Omega^{n,s}$ defined in (4.5)--(4.6) are considered, then the scheme (4.1) with $\alpha \ge \max_j \alpha_{\max}(\mathbf{U}^-_{j+\frac12},\mathbf{U}^+_{j+\frac12})$ and under the CFL condition (4.14) is globally BP, namely,
	\begin{equation}
		\mathbf{U}^n_j(x^{\tt GL}_{j,\ell}) \in \Omega^{n} 
		~~ \forall j ~ \forall \ell
		~~ \Longrightarrow ~~
		\mathbf{U}^{n+1}_j(x^{\tt GL}_{j,\ell}) \in \Omega^{n+1} 
		~~ \forall j ~ \forall \ell.
	\end{equation}
